import {mkdirSync, rmSync, writeFileSync} from 'node:fs';
import {dirname, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {build} from 'esbuild';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const output = resolve(root, 'dist/browser');
// This directory contains only files generated by this browser build.
rmSync(output, {recursive: true, force: true});
mkdirSync(output, {recursive: true});

await build({
    absWorkingDir: root,
    entryPoints: {
        standard: 'src/transform/browser/standard.ts',
        minimal: 'src/transform/browser/minimal.ts',
    },
    outdir: output,
    outExtension: {'.js': '.mjs'},
    chunkNames: 'chunks/[name]-[hash]',
    bundle: true,
    splitting: true,
    format: 'esm',
    platform: 'browser',
    target: 'es2022',
    sourcemap: true,
    legalComments: 'linked',
});

// Reexport compiler-emitted declarations, retaining one physical augmentation carrier.
// Runtime ESM is bundled separately and never executes these CommonJS declaration targets.
for (const entry of ['standard', 'minimal']) {
    writeFileSync(
        resolve(output, `${entry}.d.mts`),
        `export * from '../../lib/browser/${entry}.js';\n` +
            `export {transform as default} from '../../lib/browser/${entry}.js';\n`,
    );
}
